class Solution:
    def longestConsecutive(self, nums: list[int]) -> int:
        num_set = set(nums)
        longest = 0

        for num in num_set:
            # 只有 num - 1 不存在时，num 才是一段连续序列的起点
            if num - 1 not in num_set:
                curr = num
                length = 1
                while curr + 1 in num_set:
                    curr += 1
                    length += 1
                longest = max(longest, length)

        return longest
